function isDirty(){return state()!==savedState}
function updateSaveStatus(){const snapshot=state(),dirty=snapshot!==savedState,downloadPending=dirty&&snapshot===downloadSnapshot;const el=$("saveStatus");el.textContent=(dirty?(downloadPending?"Download angefordert – Datei prüfen":"Ungespeichert"):"Keine ungespeicherten Änderungen")+(autoSaveEnabled?(recoveryError?" · Autosicherung fehlgeschlagen":dirty&&snapshot===recoveryLast?" · Lokal gesichert":" · Autosicherung an"):" · Autosicherung aus");$("confirmDownload").disabled=!downloadPending}
