const supportOrLoad=new Set(["fixed","roller","clamp","force","moment"]);
for(const e of source){if(supportOrLoad.has(e.type)){if(selected.has(e.id)||belongs(e.link?.beam))included.add(e.id);else if(!e.link&&nearBody(e))issues.push("Nicht eindeutig zugeordnet: "+(e.label||e.type)+" – bei Bedarf ausdrücklich mit auswählen.");}
if(e.type==="load"){if(selected.has(e.id)||e.anchors?.length===2&&e.anchors.every(a=>belongs(a.id)))included.add(e.id);else if(e.anchors?.some(a=>belongs(a.id))||nearBody(e))issues.push("Streckenlast nicht vollständig zugeordnet: "+(e.label||"q")+".");}
if(["rope","bar","pulley"].includes(e.type)&&!body.has(e.id)){if(selected.has(e.id)||e.anchors?.some(a=>belongs(a.id))||belongs(e.link?.beam))issues.push("Stab-/Seil-/Rollenbindung: "+(e.label||e.type)+" – Ersatzkraft manuell ergänzen.");}}
