const isInside=(id,seen=new Set())=>{if(!id||seen.has(id))return false;seen.add(id);const e=byId.get(id);if(!e)return false;if(bodyTypes.has(e.type))return selected.has(id);if(["node","joint"].includes(e.type))return e.link?isInside(e.link.beam,seen):selected.has(id);return false};
