if(e.anchors?.length!==2)continue;
const [a,b]=e.anchors,ia=isInside(a.id),ib=isInside(b.id);
if(ia&&ib){if(!inside.has(e.id)){part.source.push(e);inside.add(e.id)}continue}
if(ia===ib)continue;
const p=ia?a:b,z=ia?b:a;
