if(!["beam","bar","joint","node","pulley"].includes(byId.get(z.id).type)){warnings.push("Unklarer Anschlusspunkt "+named.get(e.id)+" – manuell prüfen.");continue}
if([a,b].some(t=>byId.get(t.id)?.type==="pulley")){warnings.push("Seil an einer Rolle: Tangentialkräfte noch manuell ergänzen.");continue}
if(e.type==="bar"&&source.some(n=>n.id!==e.id&&(n.link?.beam===e.id||n.anchors?.some(t=>t.id===e.id)))){warnings.push("Zusätzlich belasteter Stab "+named.get(e.id)+" – Zweikraftannahme nicht automatisch zulässig.");continue}
if(Math.hypot(z.x-p.x,z.y-p.y)<1e-7){warnings.push("Bindung ohne eindeutige Richtung: "+named.get(e.id));continue}
const angle=Math.atan2(p.y-z.y,z.x-p.x)*180/Math.PI;
