const cut=freeBodyMode==="selected"?cutConnections(elements,part,freeBodySelection,{length},defaults):{reactions:0,checks:[],warnings:[]};if(freeBodyMode==="all"&&part.source.some(e=>["bar","rope","pulley","joint"].includes(e.type)))part.issues.push("Innere Bindungen bleiben erhalten; externe Stab- und Seilbindungen bitte prüfen.");if(cut.checks.length)part.issues.push("Bitte Modellannahmen bestätigen:\n"+cut.checks.join("\n"));part.issues.push(...cut.warnings);
