const station=e=>{const a=beam.angle*Math.PI/180;return ((e.x-beam.x)*Math.cos(a)-(e.y-beam.y)*Math.sin(a))/beam.length};
const near=e=>{const a=beam.angle*Math.PI/180,dx=e.x-beam.x,dy=e.y-beam.y,t=station(e);return t>=-eps&&t<=1+eps&&Math.abs(dx*Math.sin(a)+dy*Math.cos(a))<=beam.height/2+14};
